import {CLASSES,COMMON,normalizeLoadout} from './engine.mjs';
import {normalizeDuel} from './duel-setup.mjs';
import {OPPONENTS,ROUTES,DIFFICULTIES} from './opponents.mjs';
import {TENDENCIES,SPEEDS} from './auto.mjs';
export const SAVE_KEY='qingxiao.duel.save.v1',HISTORY_LIMIT=40;
const object=x=>x&&typeof x==='object'&&!Array.isArray(x),integer=(x,min=0,max=10000000)=>Number.isSafeInteger(x)&&x>=min&&x<=max;
const metricKeys=['reactionPreserved','spentAP','unusedAP','healing','overheal','intentSpent','burnConsumed','tideSpent','growthSpent','parasiteSpent','terrainSpent','forcedMoves','chillCleared','movement','hpDamage','shieldDamage','burnTaken'];
const chargeKeys=['started','released','interrupted','rangeMiss','canceled','hpDamage','shieldDamage','pending'];
function counts(x){if(!object(x))throw Error('统计无效');const result={};for(const [k,n] of Object.entries(x)){if(k.length>100||!integer(n))throw Error('统计无效');Object.defineProperty(result,k,{value:n,enumerable:true,writable:true,configurable:true});}return result;}
export function normalizeRecord(r){
 if(!object(r)||!integer(r.id,1)||!['win','lose','draw','abandoned'].includes(r.result)||!object(r.review)||!integer(r.review.rounds,1,1000)||!Array.isArray(r.review.actors)||r.review.actors.length!==2)throw Error('记录无效');
 const player=normalizeLoadout(r.player?.key,r.player),enemyKey=r.review.actors[1].key,enemy=normalizeLoadout(enemyKey,r.enemy??{major:r.review.actors[1].major});
 if(r.opponentId&&!Object.hasOwn(OPPONENTS,r.opponentId))throw Error('对手无效');if(!Object.hasOwn(DIFFICULTIES,r.difficulty??'practice'))throw Error('难度无效');
 const actors=r.review.actors.map((a,i)=>{if(!object(a)||!Object.hasOwn(CLASSES,a.key)||!integer(a.hp)||!integer(a.maxHp,1)||a.hp>a.maxHp)throw Error('角色无效');normalizeLoadout(a.key,{major:a.major});const copy={name:i===0?'你':r.opponentId?OPPONENTS[r.opponentId].name:CLASSES[a.key].person,key:a.key,major:a.major,hp:a.hp,maxHp:a.maxHp,actions:counts(a.actions),skipped:counts(a.skipped??{}),charges:{}};for(const k of metricKeys){if(!integer(a[k]??0))throw Error('统计无效');copy[k]=a[k]??0;}for(const k of chargeKeys){if(!integer(a.charges?.[k]??0))throw Error('蓄势统计无效');copy.charges[k]=a.charges?.[k]??0;}return copy;});
 if(actors[0].key!==r.player.key||actors[0].major!==player.major||actors[1].major!==enemy.major)throw Error('配装无效');
 if(!Array.isArray(r.logs)||r.logs.length>6000)throw Error('纪要无效');const logs=r.logs.map(l=>{if(!object(l)||!integer(l.round,0,1000)||typeof l.text!=='string'||l.text.length>3000)throw Error('纪要无效');return {id:integer(l.id,1)?l.id:1,round:l.round,text:l.text,type:['player','enemy','normal','setup','round','resource','hit','damage','heal','reaction','decision','charge','result'].includes(l.type)?l.type:'normal'};});
 const events=(r.review.events??[]);if(!Array.isArray(events)||events.length>4000)throw Error('回合无效');const cleanEvents=events.map(e=>{if(!object(e)||![0,1].includes(e.seat)||!integer(e.round,1,r.review.rounds)||!['action','hit','released','interrupted','rangeMiss','canceled','reaction'].includes(e.type))throw Error('回合无效');if(e.skillId&&!CLASSES[actors[e.seat].key].skills.concat(COMMON).some(s=>s.id===e.skillId))throw Error('招式无效');if(e.type==='hit'&&!integer(e.damage))throw Error('伤害无效');const x={type:e.type,seat:e.seat,round:e.round};if(e.skillId)x.skillId=e.skillId;for(const k of ['damage','shieldDamage','healing'])if(e[k]!==undefined){if(!integer(e[k]))throw Error('伤害无效');x[k]=e[k];}if(['none','shield','evade','anchor'].includes(e.response))x.response=e.response;return x;});
 return {id:r.id,run:integer(r.run,1)?r.run:null,stage:integer(r.stage,1,3)?r.stage:null,route:Object.hasOwn(ROUTES,r.route)?r.route:null,mode:r.opponentId?'challenge':'duel',portraits:{player:['male','female'].includes(r.portraits?.player)?r.portraits.player:'female',enemy:['male','female'].includes(r.portraits?.enemy)?r.portraits.enemy:'male'},opponentId:r.opponentId??null,difficulty:r.difficulty??'practice',opponent:actors[1].name,player:{key:r.player.key,...player},enemy:{key:enemyKey,...enemy},result:r.result,review:{rounds:r.review.rounds,result:r.result,distance:[0,1,2].includes(r.review.distance)?r.review.distance:1,opponentId:r.opponentId??null,difficulty:r.difficulty??'practice',actors,events:cleanEvents},logs};
}
export function normalizeSave(raw){
 if(!object(raw)||raw.version!==1)throw Error('存档版本无效');const duel=normalizeDuel(raw.duel),history=[];if(!Array.isArray(raw.history))throw Error('历史无效');const seen=new Set();let discarded=0;
 for(const r of raw.history.slice(-HISTORY_LIMIT)){try{const record=normalizeRecord(r);if(seen.has(record.id))throw Error('重复记录');seen.add(record.id);history.push(record);}catch{discarded++;}}
 const run=Math.max(integer(raw.run)?raw.run:0,...history.map(r=>r.run??0)),p=raw.progress;let progress=null;
 if(object(p)&&Object.hasOwn(ROUTES,p.route)&&Object.hasOwn(DIFFICULTIES,p.difficulty)&&integer(p.index,0,2)&&integer(p.run,1)&&p.run<=run&&Array.isArray(p.stages)&&p.stages.length===3){const stages=p.stages.map((id,i)=>i<p.index&&history.some(r=>r.id===id&&r.run===p.run&&r.stage===i+1&&r.route===p.route&&['win','lose','draw'].includes(r.result))?id:null);if(stages.slice(0,p.index).every(Boolean))progress={route:p.route,difficulty:p.difficulty,index:p.index,run:p.run,stages};}
 return {value:{version:1,duel,preferences:{route:Object.hasOwn(ROUTES,raw.preferences?.route)?raw.preferences.route:'sword',difficulty:Object.hasOwn(DIFFICULTIES,raw.preferences?.difficulty)?raw.preferences.difficulty:'practice'},automation:{tendency:Object.hasOwn(TENDENCIES,raw.automation?.tendency)?raw.automation.tendency:'balanced',speed:Object.hasOwn(SPEEDS,raw.automation?.speed)?raw.automation.speed:'normal'},history,run,progress},discarded};
}
export function createLocalStore(getStorage=()=>globalThis.localStorage){
 let cached=null;
 return {read(){try{const text=getStorage().getItem(SAVE_KEY);if(!text)return {value:null};return normalizeSave(JSON.parse(text));}catch{return {value:null,error:'本机存档暂时无法读取，已使用默认配置。'};}},write(value){try{const {value:clean}=normalizeSave({version:1,...value});let text=JSON.stringify(clean);while(new TextEncoder().encode(text).length>3000000&&clean.history.length>1){clean.history.shift();text=JSON.stringify(clean);}if(text!==cached){getStorage().setItem(SAVE_KEY,text);cached=text;}return {ok:true,savedRecords:clean.history.length};}catch{return {ok:false,error:'本机保存不可用，可复制纪要留存。'};}}};
}
